from collections.abc import Iterator


def chunk_text(text: str, max_len: int) -> list[str]:
    """Splits text into chunks of at most max_len characters based on whitespace,

    breaking excessively long words into pieces of max_len.
    """
    if max_len < 1:
        raise ValueError("max_len must be at least 1")

    def split_word(w: str) -> Iterator[str]:
        for i in range(0, len(w), max_len):
            yield w[i : i + max_len]

    words = text.split()
    if not words:
        return []

    chunks: list[str] = []
    current_chunk_words: list[str] = []
    current_length = 0

    for word in words:
        for piece in split_word(word):
            piece_len = len(piece)
            # Calculate length if we add this piece.
            # If current_chunk_words is not empty, we need 1 space separator.
            additional_chars = piece_len + (1 if current_chunk_words else 0)

            if current_length + additional_chars <= max_len:
                current_chunk_words.append(piece)
                current_length += additional_chars
            else:
                if current_chunk_words:
                    chunks.append(" ".join(current_chunk_words))
                current_chunk_words = [piece]
                current_length = piece_len

    if current_chunk_words:
        chunks.append(" ".join(current_chunk_words))

    return chunks
